result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app/main.py", "content": """"Chunked resumable uploads for FastAPI.

Flow:
    POST /uploads                 {filename, total_size, sha256} -> session id
    PUT  /uploads/{id}/chunk      header Upload-Offset appends bytes;
                                  409 Conflict if offset != bytes received so far
    POST /uploads/{id}/complete   verifies total size + sha256 of assembled file;
                                  422 Unprocessable Entity on mismatch
"""

import hashlib
import shutil
import uuid
from pathlib import Path

from fastapi import Depends, FastAPI, Header, HTTPException, Request
from pydantic import BaseModel, Field

UPLOAD_ROOT = Path("uploads")

app = FastAPI(title="Chunked Resumable Uploads")


class UploadSession:
    """Server-side state for one in-progress upload."""

    __slots__ = ("id", "filename", "total_size", "sha256", "path", "bytes_received")

    def __init__(self, filename: str, total_size: int, sha256: str) -> None:
        self.id = uuid.uuid4().hex
        self.filename = filename
        self.total_size = total_size
        self.sha256 = sha256.lower()
        self.path = UPLOAD_ROOT / f"{self.id}.part"
        self.bytes_received = 0


class SessionStore:
    def __init__(self) -> None:
        self._sessions: dict[str, UploadSession] = {}

    def create(self, filename: str, total_size: int, sha256: str) -> UploadSession:
        if total_size <= 0:
            raise HTTPException(422, "total_size must be positive")
        session = UploadSession(filename, total_size, sha256)
        self._sessions[session.id] = session
        return session

    def get(self, upload_id: str) -> UploadSession:
        session = self._sessions.get(upload_id)
        if session is None:
            raise HTTPException(404, "upload session not found")
        return session


def get_store() -> SessionStore:
    return store


store = SessionStore()


class CreateUploadRequest(BaseModel):
    filename: str = Field(min_length=1)
    total_size: int = Field(gt=0)
    sha256: str = Field(min_length=64, max_length=64)


@app.post("/uploads", status_code=201)
def create_upload(body: CreateUploadRequest, _: SessionStore = Depends(get_store)):
    session = store.create(body.filename, body.total_size, body.sha256)
    UPLOAD_ROOT.mkdir(parents=True, exist_ok=True)
    session.path.touch()
    return {
        "upload_id": session.id,
        "filename": session.filename,
        "total_size": session.total_size,
        "sha256": session.sha256,
        "bytes_received": session.bytes_received,
    }


@app.put("/uploads/{upload_id}/chunk")
async def put_chunk(
    upload_id: str,
    request: Request,
    upload_offset: int = Header(...),
    _: SessionStore = Depends(get_store),
):
    session = store.get(upload_id)

    # Out-of-order / duplicate chunk defense: only the exact next byte
    # position may be appended.
    if upload_offset != session.bytes_received:
        raise HTTPException(
            409,
            detail={
                "error": "offset mismatch",
                "expected_offset": session.bytes_received,
                "received_offset": upload_offset,
            },
        )

    body = await request.body()
    if not body:
        raise HTTPException(422, "empty chunk")
    if session.bytes_received + len(body) > session.total_size:
        raise HTTPException(422, "chunk exceeds declared total_size")

    # O_APPEND keeps concurrent writers from clobbering each other; the
    # offset check above serializes the logical order anyway.
    with open(session.path, "ab") as fh:
        fh.write(body)
    session.bytes_received += len(body)

    return {"bytes_received": session.bytes_received, "complete": False}


@app.post("/uploads/{upload_id}/complete")
def complete_upload(upload_id: str, _: SessionStore = Depends(get_store)):
    session = store.get(upload_id)

    if session.bytes_received != session.total_size:
        raise HTTPException(
            422,
            detail={
                "error": "incomplete upload",
                "bytes_received": session.bytes_received,
                "total_size": session.total_size,
            },
        )

    digest = hashlib.sha256()
    with open(session.path, "rb") as fh:
        for block in iter(lambda: fh.read(1024 * 1024), b""):
            digest.update(block)
    actual = digest.hexdigest()

    if actual != session.sha256:
        raise HTTPException(
            422,
            detail={"error": "sha256 mismatch", "expected": session.sha256, "actual": actual},
        )

    final_path = UPLOAD_ROOT / session.id / session.filename
    final_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(session.path, final_path)

    return {
        "upload_id": session.id,
        "filename": session.filename,
        "size": session.bytes_received,
        "sha256": actual,
        "status": "complete",
    }


@app.get("/uploads/{upload_id}")
def upload_status(upload_id: str, _: SessionStore = Depends(get_store)):
    session = store.get(upload_id)
    return {
        "upload_id": session.id,
        "filename": session.filename,
        "total_size": session.total_size,
        "bytes_received": session.bytes_received,
    }
